const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable ATmega328P built-in 30k pullup
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int state = digitalRead(buttonPin);
  if (state == LOW) { // Active-Low: Pressed shorts pin to GND
    digitalWrite(ledPin, HIGH);
    Serial.println("BUMP DETECTED!");
  } else {
    digitalWrite(ledPin, LOW);
  }
}
